BEGIN;SET LOCAL statement_timeout='10s';SET LOCAL lock_timeout='1s';ALTER TABLE public.lead_commercial ADD COLUMN IF NOT EXISTS awaiting_response_since timestamptz,ADD COLUMN IF NOT EXISTS response_deadline_at timestamptz;COMMENT ON COLUMN public.lead_commercial.awaiting_response_since IS 'Instante materializado que iniciou/reiniciou a espera por resposta.';COMMENT ON COLUMN public.lead_commercial.response_deadline_at IS 'Prazo materializado para aguardando_resposta -> recusado.';COMMIT;
